/* LOOKteracy 공통 화면 조각, 지문·학급 예시 데이터, 화면 상태(st), 경로(route)와 그리기(render).
   카메라·페이스패스·시선 추적·채점은 뒤에 읽는 facepass.js, gaze.js, grading.js, insight.js가 이 파일의 함수를 감싸서 더한다. */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=escapeHTML;
const badge=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
const av=(n,c='')=>`<span class="avatar ${c}" aria-hidden="true">${esc(n.slice(-2,-1)||n[0])}</span>`;
const brand=()=>publicWordmark();
const button=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const link=(text,to,cls='link-btn')=>`<a class="${cls}" href="#${to}" data-route="${to}">${text}</a>`;
const note=(text,cls='')=>`<div class="note ${cls}">${icon('info')}<span>${text}</span></div>`;
const head=(title,desc,actions='')=>`<div class="page-head"><div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const field=(label,key,val='',type='text',placeholder='')=>`<label class="field">${label}<input class="input" type="${type}" data-bind="${key}" value="${esc(val)}" placeholder="${esc(placeholder)}"></label>`;
const textfield=(label,key,val,cls='')=>`<label class="field">${label}<textarea data-bind="${key}" class="${cls}">${esc(val)}</textarea></label>`;
const tabs=(items,current,key)=>`<div class="tabs" role="tablist">${items.map(([id,t])=>`<button role="tab" aria-selected="${current===id}" class="${current===id?'active':''}" data-tab="${key}" data-value="${id}">${t}</button>`).join('')}</div>`;
const stepper=(labels,current)=>`<div class="steps">${labels.map((l,i)=>`<span class="${current===i?'active':''}"><i>${i+1}</i>${l}</span>${i<labels.length-1?'<span aria-hidden="true">—</span>':''}`).join('')}</div>`;
const domains=['읽기 유창성','핵심 내용 파악','맥락 파악','추론 능력','비판적 읽기'];
const passageTitle='호작도 속 호랑이와 까치의 의미';
const paras=[
 ['안녕하세요?','발표자 ○○○입니다.','최근 케이팝을 소재로 한 애니메이션에 등장하는 호랑이와 까치가 인기를 끌었습니다.','이 호랑이와 까치는 조선 시대 민화 호작도에서 이어져 온 전통적 이미지를 활용한 것입니다.','호작도는 호랑이와 까치를 한 화면에 그린 그림인데요, 오늘은 호작도 속에서 호랑이와 까치가 어떤 상징적 의미를 지니는지 살펴보겠습니다.'],
 ['(자료를 제시하며) 그럼, ㉠[[여기]] 호작도를 볼까요?','호작도는 보통 나무 아래에 호랑이를, 위에는 까치를 배치해 당대 사람들의 인식과 바람을 담아냈습니다.','호랑이는, 예로부터 호랑이로 인한 화를 뜻하는 호환이라는 말이 있을 만큼 위협적인 공포의 대상이었습니다.','하지만 사람들은 그 압도적인 힘이 액운을 물리칠 수 있다고 믿었고, 그 결과 호랑이를 나쁜 기운을 막아 주는 수호자로 받아들였습니다.'],
 ['(자료의 호랑이를 가리키며) ㉡[[그런데]] 이 그림 속 호랑이, 수호자처럼 보이시나요?','(청중의 대답을 듣고) 그렇습니다.','어딘지 의연하고 듬직한 모습은 아닙니다.','(엄지와 검지로 원을 만들며) 눈은 이렇게 과장되게 크고, 발도 뭉툭하지요.','㉢[[이]]는 호랑이를 익살스럽게 그림으로써 친근한 존재로 곁에 두고 싶어 했던 심리가 반영된 것입니다.','(자료의 까치를 가리키며) 자, 이번에는 여기 있는 까치에 대해 알아보겠습니다.','혹시 까치에 대한 속담에는 무엇이 있는지 아시나요?','(청중의 대답을 듣고) 네, 그렇죠.','‘까치가 울면 반가운 손님이 온다.’라는 속담이 있습니다.','이처럼 까치는 기쁜 소식을 전하는 길조로 알려져 있습니다.','호작도에 길조인 까치를 그려 넣은 것은 복을 기원하는 민중의 소망이 반영된 것입니다.']
];
// 출처: 26년 고1 3월 모의고사 (1~3) 지문. [[ ]]는 원문의 밑줄(㉠~㉢)이며, 화면에서는 밑줄로 그리고 그 밖의 곳에서는 기호를 뺀다.
const plainSentence=s=>s.replace(/\[\[|\]\]/g,'');
const richSentence=s=>esc(s).replace(/\[\[(.+?)\]\]/g,'<u class="passage-mark">$1</u>');
const sentences=paras.flat().map(plainSentence);
const passagePlain=paras.map(p=>p.map(plainSentence).join(' ')).join('\n\n');
const initialFeedback={strength:'발표가 다루는 중심 대상인 호작도와 그림의 배치(나무 아래 호랑이, 위의 까치)를 정확히 짚었어요.',concept:'호랑이가 공포의 대상에서 액운을 막는 수호자로, 다시 익살스럽고 친근한 존재로 받아들여진 흐름을 ‘하지만’, ‘그런데’를 중심으로 연결해 보세요.',strategy:'모르는 낱말이 나오면 앞뒤 한 문장을 함께 읽어 뜻을 짐작하고, 상징의 의미를 내 말로 한 문장씩 정리해 보세요.'};
const studentNames=['김서윤','이지우','박하린','최도윤','정수아','윤지호','한예린','오민재','이서준','강다은'];
const baseStatus=['분석 완료','분석 완료','제출 완료','응시 중','분석 완료','분석 완료','분석 완료','준비 중','준비 실패','시작 전'];
