const st={role,page:'landing',signup:0,signupName:'',signupCode:'',registered:false,faceScan:false,paused:false,prep:0,cal:0,ready:false,readDone:false,q:0,mode:'typing',answers:['','',''],ink:{1:[],2:[]},ocr:'',ocrConfirmed:false,submitted:false,filter:'전체',search:'',tab:'talk',quote:null,comments:[],summary:'',groupSubmitted:false,aiQuestion:0,optionalStarted:false,optionalHint:false,optionalDone:false,optionalAnswer:'',resourceTab:'passages',resourceSearch:'',extraResources:[],builderTab:'passage',testTitle:passageTitle,testText:passagePlain,compare:false,assigned:false,feedbackDraft:{...initialFeedback},published:{...initialFeedback},feedbackVersion:1,publishedRead:false,reportStudent:'김서윤',reportTab:'heat',reportFinal:false,feedbackStudent:'김서윤',groups:{김서윤:0,이지우:0,박하린:0,최도윤:0,정수아:1,윤지호:1,한예린:1,오민재:1},groupsConfirmed:true,groupGoal:'호랑이와 까치의 상징을 근거와 연결해 설명하기',groupTask:'호랑이가 두려움의 대상에서 친근한 수호자로 받아들여진 까닭을 발표 속 근거 두 개와 함께 설명하고, 모둠의 요약문을 작성하세요.',teacherGroupFeedback:'',groupAssigned:true,font:20,round:'3회차 · 호작도와 상징',className:'1학년 2반'};
const menuStudent=[['s-home','home','홈'],['s-tests','book','나의 테스트'],['s-feedback','spark','피드백·추천 학습'],['s-group','group','우리 모둠'],['s-history','clock','학습 기록'],['s-settings','settings','설정']];
const menuTeacher=[['t-dashboard','home','대시보드'],['t-builder','book','수업·테스트'],['t-report','chart','진단·피드백'],['t-groups','group','그룹 관리'],['t-library','list','자료실'],['t-class','group','학급·학생'],['t-settings','settings','설정']];
const names={landing:'서비스 안내','login-student':'페이스패스 로그인','login-teacher':'교사 로그인',signup:'학생 가입·등록','s-home':'학생 홈','s-tests':'나의 테스트','s-prep':'학습 준비','s-reading':'지문 읽기','s-answer':'문항 응답','s-complete':'제출 완료','s-feedback':'피드백·추천 학습','s-group':'우리 모둠','s-history':'학습 기록','s-settings':'설정','t-dashboard':'교사 대시보드','t-builder':'테스트 구성·배정','t-monitor':'응시 현황','t-report':'학생 상세 리포트','t-feedback':'피드백 편집','t-groups':'그룹 관리', 't-group-detail':'테스트별 그룹 편성','t-operation':'모둠 운영','t-library':'자료실','t-class':'학급·학생 관리','t-settings':'설정'};
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(title,body){const n=$('#modal');if(n.open)n.close();n.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div>`;n.showModal()}
function publicHeader(){return `<header class="public-nav">${link(publicWordmark(),'landing','brand public-wordmark')}</header>`}
function publicFooter(){return `<footer class="public-footer"><span>LOOKteracy · 읽는 과정을 이해하는 새로운 시선</span><span>고등학교 국어·독서 수업을 위한 학습 공간</span></footer>`}
function tracking(){return renderReadingVisual()}
function landing(){return renderLanding()}
function faceFrame(success=false){return `<div class="face-frame" role="img" aria-label="얼굴을 안내선 안에 맞추는 페이스패스 화면"><div class="face-shoulders"></div><div class="face-outline"></div>${['tl','tr','bl','br'].map(c=>`<i class="face-corner ${c}"></i>`).join('')}${success?`<span class="face-check">${icon('check')}</span>`:'<i class="face-scan"></i>'}<span class="face-label">페이스패스</span></div>`}
function login(student){return `<div class="public login-shell">${publicHeader()}<main class="auth-wrap" id="main" tabindex="-1"><div class="auth-intro"><span class="eyebrow">${student?'WELCOME BACK':'FOR TEACHERS'}</span><h1>${student?'오늘의 읽기,<br>여기서 시작해요.':'우리 반의 읽기를<br>함께 살펴봐요.'}</h1><p>${student?'배정된 테스트와 선생님의 피드백을<br>나의 학습 공간에서 만나보세요.':'수업 준비부터 피드백까지,<br>학생의 배움을 한곳에서 이어 가세요.'}</p></div><section class="auth-card"><div class="auth-card-heading"><h2>${student?'페이스패스 로그인':'교사 로그인'}</h2><p>${student?'안내선 안에 얼굴을 맞춰 주세요.':'교사 계정으로 로그인해 주세요.'}</p></div>${student?`${faceFrame(st.faceScan)}<div class="face-state ${st.faceScan?'is-ready':''}" role="status">${st.faceScan?icon('check')+'얼굴 확인이 완료되었어요.':'밝은 곳에서 정면을 바라봐 주세요.'}</div>${button(st.faceScan?'다시 확인하기':'얼굴 확인하기','face-preview','secondary full face-preview-button')}`:`${field('이메일','email','','email','이메일 주소')}${field('비밀번호','password','','password','비밀번호')}`}${button(`로그인 ${icon('arrow')}`,student?'login-student':'login-teacher','full auth-login-button')}<div class="auth-account-links">${student?'<span>처음 이용하나요?</span><button data-route="signup">학급 연결·페이스패스 등록</button><button class="teacher-preview-access" data-action="teacher-preview-access" aria-label="선생님 페이지 열기" title="선생님 페이지 열기">'+icon('check')+'</button>':'<button data-action="teacher-help">계정 이용 안내</button>'}</div><div class="auth-secondary-links">${student?'<button data-action="face-help">로그인 도움</button>':'<button data-route="login-student">페이스패스 로그인 '+icon('arrow')+'</button>'}</div></section></main>${publicFooter()}</div>`}
function signup(){let body='';if(st.signup===0)body=`${field('이름','signupName',st.signupName,'text','이름을 입력해 주세요')}${field('학급 연결 코드','signupCode',st.signupCode,'text','선생님에게 받은 코드를 입력하세요')}<div class="source-box">${badge('연결할 학급','blue')}<h3 style="margin-top:12px">인하고등학교 · 1학년 2반</h3><p class="small">김하늘 선생님 · 담당 학급</p></div>`;if(st.signup===1)body=`<div class="rubric"><h3>어떤 정보를, 왜 사용하나요?</h3><p>학급 연결 정보, 시선 좌표·읽기 시간, 문항 응답, 협력 활동 기록을 학습 지원과 교사의 지도에 활용해요.</p></div><div class="rubric"><h3>영상과 보관에 대해 알려드려요</h3><p>카메라 영상은 저장하지 않아요. 학습 기록은 삭제하기 전까지 보관해요.</p></div><div class="rubric"><h3>페이스패스 정보는 이렇게 저장해요</h3><p>얼굴 사진 대신 얼굴 특징값만 이 기기의 브라우저에 저장해요.</p></div><label class="check-row"><input type="checkbox"><span>수집·활용·보관 안내를 확인했어요</span></label><label class="check-row"><input type="checkbox"><span>필요한 동의·확인 절차를 마쳤어요</span></label>`;if(st.signup===2)body=`<p class="small">등록한 얼굴을 학생 계정과 연결하는 화면이에요.</p>${faceFrame(st.registered)}<div class="face-state">${st.registered?'페이스패스 등록을 마쳤어요.':'밝은 곳에서 정면을 바라보고 얼굴을 맞춰 주세요.'}</div>${button(st.registered?'다시 등록하기':'페이스패스 등록하기','register-face','secondary full')}`;return `<div class="public">${publicHeader()}<main class="signup-wrap" id="main" tabindex="-1"><section class="auth-card"><span class="eyebrow">WELCOME TO LOOKTERACY</span><h1 style="font-size:28px;margin:12px 0">나의 읽기 공간을 준비해요</h1>${stepper(['학급 연결','수집·보관 안내','페이스패스 등록'],st.signup)}${body}<div class="signup-nav">${button(st.signup?'이전':'로그인으로','signup-back','secondary')}${button(st.signup===2?'등록 완료 · 로그인으로':'다음 단계 '+icon('arrow'),'signup-next')}</div></section></main>${publicFooter()}</div>`}
function currentNav(){if(st.role==='student'){if(['s-prep','s-reading','s-answer','s-complete'].includes(st.page))return's-tests';return st.page}if(['t-monitor'].includes(st.page))return't-builder';if(st.page==='t-feedback')return't-report';if(['t-operation','t-group-detail'].includes(st.page))return't-groups';return st.page}
function shell(content){const teacher=st.role==='teacher';const menu=teacher?menuTeacher:menuStudent;return `<aside class="sidebar">${link(brand(),teacher?'t-dashboard':'s-home','brand')}<div class="class-box"><span class="micro">나의 교실</span><strong>인하고등학교 · ${st.className}</strong></div><div class="nav-label">${teacher?'수업과 지도':'나의 학습 공간'}</div><nav class="app-nav" aria-label="${teacher?'교사':'학생'} 메뉴">${menu.map(([p,i,t])=>`<a href="#${p}" data-route="${p}" class="${currentNav()===p?'active':''}" ${currentNav()===p?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${t}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>읽는 과정에서 시작되는 배움</strong>${teacher?'관찰을 해석으로,<br>해석을 다음 수업으로.':'나의 속도로 읽고,<br>근거를 함께 발견해요.'}</div><button data-action="help">${icon('help')}이용 안내</button><button data-action="logout">${icon('back')}로그아웃</button></div></aside><div class="workspace"><header class="topbar">${link(brand(),teacher?'t-dashboard':'s-home','mobile-wordmark')}<div class="breadcrumb"><span>${teacher?'교사':'학생'} 공간</span>${icon('chevron')}<strong>${names[st.page]}</strong></div><div class="top-right"><span class="app-role">${teacher?'TEACHER':'STUDENT'}</span><div class="profile">${av(teacher?'김하늘':'김서윤')}<strong>${teacher?'김하늘':'김서윤'}<small>${teacher?'선생님':'학생'}</small></strong></div><button class="icon-btn" data-action="logout" aria-label="로그아웃">${icon('back')}</button></div></header><main id="main" tabindex="-1">${content}</main><footer class="app-footer"><span>LOOKteracy · ${teacher?'교사':'학생'} 전용 공간</span></footer></div>`}
function safePage(p){if(!Object.hasOwn(names,p))return st.role==='teacher'?'t-dashboard':st.role==='student'?'s-home':'landing';if(!st.role&&/^[st]-/.test(p))return p[0]==='s'?'login-student':'login-teacher';if(st.role&&(!/^[st]-/.test(p)||p[0]!==st.role[0]))return st.role==='teacher'?'t-dashboard':'s-home';if(p==='s-reading'&&!st.ready)return 's-prep';if(p==='s-answer'&&!st.readDone)return st.ready?'s-reading':'s-prep';return p}
function route(p,replace=false){const safe=safePage(p);if(safe!==p&&st.role)toast(/^[st]-/.test(p)&&p[0]!==st.role[0]?'다른 역할의 화면은 로그아웃 후 접속할 수 있어요.':'현재 로그인과 학습 단계에 맞는 화면으로 이동했어요.');st.page=safe;history[replace?'replaceState':'pushState'](null,'','#'+safe);$('#modal').close();render();scrollTo(0,0);$('#main')?.focus({preventScroll:true})}
function render(){stopCalibrationMotion();stopLandingAnimation();document.body.classList.toggle('student-home-page',st.page==='s-home');document.title=`${names[st.page]} · LOOKteracy`;document.documentElement.style.setProperty('--read-size',st.font+'px');const publicPage=st.page==='landing'?landing():st.page==='signup'?signup():st.page==='login-student'?login(true):st.page==='login-teacher'?login(false):null;$('#app').innerHTML=publicPage??shell(views[st.page]());if(st.page==='landing')requestAnimationFrame(setupLandingAnimation);if(st.page==='s-answer'&&st.q>0&&st.mode==='hand')requestAnimationFrame(setupInk)}
